describe('Search Result Snippets with Highlighted Terms', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display search terms highlighted in result snippets', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('/api/search');
      expect(req.body.query).to.equal('Cypress');
    }).as('searchRequest');

    // Perform search
    cy.get('[data-testid="search-input"]').type('Cypress');
    cy.get('[data-testid="search-button"]').click();

    // Wait for search results to load
    cy.wait('@searchRequest');

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);

    // Verify highlighted terms are present in the first result snippet
    cy.get('[data-testid="search-result-item"]').first().should('contain', '<mark class="highlight">Cypress</mark>');

    // Verify highlighted term is styled correctly
    cy.get('[data-testid="search-result-item"]').first().should('have.css', 'mark.color', 'rgba(255, 0, 0, 0.5)');

    // Verify other search terms are also highlighted
    cy.get('[data-testid="search-result-item"]').first().should('contain', '<mark class="highlight">automation</mark>');

    // Verify highlighted terms are not present in non-matching results
    cy.get('[data-testid="search-result-item"]').last().should('not.contain', '<mark class="highlight">Cypress</mark>');
  });

  it('should handle empty search term and display no results', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*', (req) => {
      expect(req.url).to.include('/api/search');
      expect(req.body.query).to.equal('');
    }).as('emptySearchRequest');

    // Perform empty search
    cy.get('[data-testid="search-input"]').clear().type('');
    cy.get('[data-testid="search-button"]').click();

    // Wait for empty search results
    cy.wait('@emptySearchRequest');

    // Verify no results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length', 0);

    // Verify empty state message is displayed
    cy.get('[data-testid="empty-state-message"]').should('be.visible');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No results found');
  });
});
